insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000101', 0, 'Inedible', 'Dishes were left unfinished or sent back. Something was unsafe, spoiled or badly wrong.'),
  ('00000000-0000-4000-a002-000000000101', 1, 'Poor', 'Most dishes had clear flaws: bland, greasy, over- or under-cooked. You would not order any of it again.'),
  ('00000000-0000-4000-a002-000000000101', 2, 'Uneven', 'One or two things were fine, but the meal as a whole was forgettable or inconsistent.'),
  ('00000000-0000-4000-a002-000000000101', 3, 'Good', 'Solid, enjoyable cooking with no real mistakes. You left satisfied, though nothing stood out.'),
  ('00000000-0000-4000-a002-000000000101', 4, 'Very good', 'Well-made food with at least one dish you would come back for specifically.'),
  ('00000000-0000-4000-a002-000000000101', 5, 'Exceptional', 'Memorable from start to finish. Every dish was excellent and several were among the best of their kind you have had.');
