insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000102', 0, 'Let you down', 'Rude, absent or disorganised. Service made the visit worse.'),
  ('00000000-0000-4000-a002-000000000102', 1, 'Fine', 'Polite and functional, with small lapses such as slow check-ins or a forgotten request.'),
  ('00000000-0000-4000-a002-000000000102', 2, 'Excellent', 'Warm, attentive and well paced. Staff knew the menu and you never had to chase anything.');
