insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000103', 0, 'Overpriced', 'The bill felt out of line with the quality or portions. You would not pay this again.'),
  ('00000000-0000-4000-a002-000000000103', 1, 'Fair', 'About what you expected to pay for a meal of this quality.'),
  ('00000000-0000-4000-a002-000000000103', 2, 'Great value', 'The quality and care clearly exceeded the price, whatever that price was.');
