insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000104', 0, 'Detracted', 'The space got in the way: uncomfortable, unclean, or too loud to enjoy the meal.'),
  ('00000000-0000-4000-a002-000000000104', 1, 'Fits the place', 'Comfortable and clean, with a setting that suits the restaurant''s style and added to the visit.');
