insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000201', 0, 'Failed', 'Serious technical faults or dishes that simply did not work. Well below what the format promises.'),
  ('00000000-0000-4000-a002-000000000201', 1, 'Below the bar', 'Competent in places but with several weak or muddled courses for a restaurant at this level.'),
  ('00000000-0000-4000-a002-000000000201', 2, 'Accomplished', 'Skilled, polished cooking with good ingredients, but few surprises and a course or two that fell flat.'),
  ('00000000-0000-4000-a002-000000000201', 3, 'Excellent', 'Precise and distinctive cooking. Nearly every course landed and a couple were outstanding.'),
  ('00000000-0000-4000-a002-000000000201', 4, 'Extraordinary', 'A complete, original menu with no weak course. Food you will remember and describe to people for years.');
insert into public.ranking_criteria (id, version_id, position, name, guidance, max_points)
insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000202', 0, 'Poor', 'Inattentive, stiff or careless. Long unexplained waits or mistakes that were not put right.'),
  ('00000000-0000-4000-a002-000000000202', 1, 'Adequate', 'Correct but impersonal or uneven. Courses were paced awkwardly or questions went unanswered.'),
  ('00000000-0000-4000-a002-000000000202', 2, 'Polished', 'Knowledgeable and well paced, with only minor slips. You felt looked after.'),
  ('00000000-0000-4000-a002-000000000202', 3, 'Seamless', 'Anticipated what you needed before you asked. Warm, exact and unobtrusive from arrival to goodbye.');
insert into public.ranking_criteria (id, version_id, position, name, guidance, max_points)
insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000203', 0, 'Undermined the meal', 'Cramped, noisy, tired or uncomfortable in a way that worked against the experience.'),
  ('00000000-0000-4000-a002-000000000203', 1, 'Pleasant', 'A comfortable, well-kept room that did its job without adding much.'),
  ('00000000-0000-4000-a002-000000000203', 2, 'Transporting', 'A considered space where the design, comfort and mood made the evening feel like an occasion.');
insert into public.ranking_criteria (id, version_id, position, name, guidance, max_points)
insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000204', 0, 'Not worth it', 'The experience did not justify the price, even by fine-dining standards.'),
  ('00000000-0000-4000-a002-000000000204', 1, 'Worth it', 'You would pay this again for the same experience.');
