insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000301', 0, 'Inedible', 'Stale, cold or wrong enough that you did not finish it.'),
  ('00000000-0000-4000-a002-000000000301', 1, 'Poor', 'Low-quality ingredients or careless cooking. Not worth the calories.'),
  ('00000000-0000-4000-a002-000000000301', 2, 'Passable', 'Filled a gap. Nothing wrong enough to complain about, nothing good enough to return for.'),
  ('00000000-0000-4000-a002-000000000301', 3, 'Good', 'Fresh, tasty and reliably made. A dependable choice when you are nearby.'),
  ('00000000-0000-4000-a002-000000000301', 4, 'Very good', 'Clearly better than most places of its kind. Worth a detour.'),
  ('00000000-0000-4000-a002-000000000301', 5, 'Best in class', 'Among the best versions of this food you have eaten anywhere. Worth a special trip.');
