insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000302', 0, 'Rip-off', 'Small portions or poor quality for a price well above comparable places.'),
  ('00000000-0000-4000-a002-000000000302', 1, 'Pricey', 'A little more than it should cost for what you get.'),
  ('00000000-0000-4000-a002-000000000302', 2, 'Fair', 'A reasonable price for a filling, decent meal.'),
  ('00000000-0000-4000-a002-000000000302', 3, 'A bargain', 'Generous and high quality for the money. You would happily pay more.');
