insert into public.criterion_score_levels (criterion_id, points, label, description) values
  ('00000000-0000-4000-a002-000000000303', 0, 'Slow or wrong', 'A long wait with no explanation, or the order was wrong and not fixed.'),
  ('00000000-0000-4000-a002-000000000303', 1, 'Acceptable', 'A reasonable wait, or a small mistake that was corrected without fuss.'),
